            if not self._verify_reference(reference_node, signature_node):
                return False

        signed_info_c14n = self._canonicalize(signed_info)
        if signed_info_c14n is None:
            return False

        hash_algorithm = self._get_signature_method(signed_info)

        sig_value_nodes = signature_node.xpath(
            './ds:SignatureValue',
            namespaces=self.NAMESPACES
        )

        if not sig_value_nodes:
            return False

        signature_value_text = sig_value_nodes[0].text
        if not signature_value_text:
            return False

        signature_value = base64.b64decode(signature_value_text.strip())

        try:
            self.public_key.verify(
                signature_value,
                signed_info_c14n,
                padding.PKCS1v15(),
                hash_algorithm
            )
            return True
        except Exception as e:
            return False

    except Exception as e:
        return False

def _validate_time_conditions(self):
    try:
        conditions_nodes = self.document.xpath(
            '//saml:Conditions',
            namespaces=self.NAMESPACES
        )

        if not conditions_nodes:
            return True

        now = datetime.utcnow()
        tolerance = timedelta(seconds=self.time_tolerance)

        for conditions in conditions_nodes:
            not_before = conditions.get('NotBefore')
            if not_before:
                not_before_time = self._parse_time(not_before)
                if not_before_time and now < (not_before_time - tolerance):
                    return False

            not_on_or_after = conditions.get('NotOnOrAfter')
            if not_on_or_after:
                not_on_or_after_time = self._parse_time(not_on_or_after)
                if not_on_or_after_time and now > (not_on_or_after_time + tolerance):
                    return False

        confirmation_data_nodes = self.document.xpath(
            '//saml:SubjectConfirmationData',
            namespaces=self.NAMESPACES
        )

        for confirmation_data in confirmation_data_nodes:
            not_on_or_after = confirmation_data.get('NotOnOrAfter')
            if not_on_or_after:
                not_on_or_after_time = self._parse_time(not_on_or_after)
                if not_on_or_after_time and now > (not_on_or_after_time + tolerance):
                    return False

        return True
    except Exception:
        return False

def _validate_audience_restriction(self):
    """
    """
    try:
        if not self.expected_audience:
            return True

        audience_nodes = self.document.xpath(
            '//saml:Audience',
            namespaces=self.NAMESPACES
        )

        if not audience_nodes:
            return False

        for audience in audience_nodes:
            if audience.text and audience.text.strip() == self.expected_audience:
                return True

        return False
    except Exception:
        return False

def _validate_destination(self):
    """
    """
    try:
        if not self.expected_destination:
            return True

        response_nodes = self.document.xpath(
            '//samlp:Response',
            namespaces=self.NAMESPACES
        )

        for response in response_nodes:
            destination = response.get('Destination')
            if destination and destination != self.expected_destination:
                return False

        confirmation_data_nodes = self.document.xpath(
            '//saml:SubjectConfirmationData',
            namespaces=self.NAMESPACES
        )

        for confirmation_data in confirmation_data_nodes:
            recipient = confirmation_data.get('Recipient')
            if recipient and recipient != self.expected_destination:
                return False

        return True
    except Exception:
        return False

def _parse_time(self, time_str):
    """
    """
    try:
        formats = [
            '%Y-%m-%dT%H:%M:%S.%fZ',  # 2025-11-14T20:56:00.965Z
            '%Y-%m-%dT%H:%M:%SZ',     # 2025-11-14T20:56:00Z
            '%Y-%m-%dT%H:%M:%S',      # 2025-11-14T20:56:00
        ]

        for fmt in formats:
            try:
                return datetime.strptime(time_str, fmt)
            except ValueError:
                continue

        return None
    except Exception:
        return None

def get_assertion_ids(self):
    """
    """
    try:
        assertion_nodes = self.document.xpath(
            '//saml:Assertion',
            namespaces=self.NAMESPACES
        )

        ids = []
        for assertion in assertion_nodes:
            assertion_id = assertion.get('ID')
            if assertion_id:
                ids.append(assertion_id)

        return ids
    except Exception:
        return []

const SAMLIdentityProvider = require('../utils/saml');
const config = require('../config/config');

class SAMLService {
    static getIdentityProvider() {
        if (!this.idp) {
            const certificate = config.getCertificate();
            const privateKey = config.getPrivateKey();
            const samlConfig = config.getSamlConfig();

            this.idp = new SAMLIdentityProvider({
                issuer: process.env.SAML_ISSUER || samlConfig.issuer,
                certificate: certificate,
                privateKey: privateKey
            });
        }
        return this.idp;
    }

    static async generateSAMLResponse(user, options = {}) {
        const idp = this.getIdentityProvider();

        const userInfo = {
            id: user.id,
            uid: String(user.id || ''),
            username: user.username || '',
            email: user.email || user.username || '',
            displayName: user.display_name || user.username || '',
            display_name: user.display_name || user.username || '',
            role: user.role || 'user',
            department: user.department || ''
        };

        const responseOptions = {
            requestId: options.requestId,
            acsUrl: options.acsUrl || options.acs_url,
            destination: options.acsUrl || options.acs_url,
            entityId: options.entityId || options.entity_id,
            audience: options.entityId || options.entity_id,
            nameIDFormat: options.nameIDFormat || 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified'
        };

        const responseXml = idp.createLoginResponse(userInfo, responseOptions);
        return SAMLIdentityProvider.encodeResponse(responseXml);
    }

    static async parseSAMLRequest(samlRequest, binding = 'redirect') {
        try {
            const idp = this.getIdentityProvider();
            const parsed = idp.parseAuthnRequest(samlRequest, binding);

            return {
                requestId: parsed.requestId,
                acsUrl: parsed.acsUrl,
                entityId: parsed.issuer,
                issueInstant: parsed.issueInstant,
                destination: parsed.destination,
                protocolBinding: parsed.protocolBinding,
                forceAuthn: parsed.forceAuthn,
                isPassive: parsed.isPassive,
                nameIDFormat: parsed.nameIDFormat,
                allowCreate: parsed.allowCreate
            };
        } catch (error) {
            console.error('[SAML Service] Failed to parse SAML request:', error.message);
            return null;
        }
    }

    static async validateSAMLRequest(samlRequest) {
        if (!samlRequest) {
            return { valid: false, message: 'Missing SAML request' };
        }

        try {
            const parsed = await this.parseSAMLRequest(samlRequest);
            if (!parsed) {
                return { valid: false, message: 'Invalid SAML request format' };
            }
            return { valid: true, data: parsed };
        } catch (error) {
            console.error('[SAML Service] SAML request validation failed:', error.message);
            return { valid: false, message: error.message };
        }
    }

    static async validateRequestId(requestId, issueInstant) {
        const idp = this.getIdentityProvider();
        return idp.validateRequestId(requestId, issueInstant);
    }

    static generateMetadata() {
        try {
            const idp = this.getIdentityProvider();
            const serverConfig = config.getServerConfig();
            const samlConfig = config.getSamlConfig();
            const baseUrl = process.env.BASE_URL || `http://${serverConfig.host}:${serverConfig.port}`;

            return idp.getMetadata({
                entityID: process.env.SAML_ISSUER || samlConfig.issuer,
                ssoLocation: `${baseUrl}/saml/sso`,
                sloLocation: `${baseUrl}/saml/slo`,
                nameIDFormats: ['urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified']
            });
        } catch (error) {
            console.error('[SAML Service] Failed to generate metadata:', error.message);
            console.error(error);
            throw error;
        }
    }

    static async generateSAMLLogoutResponse(options = {}) {
        try {
            const idp = this.getIdentityProvider();

            const logoutResponseOptions = {
                inResponseTo: options.inResponseTo,
                destination: options.destination || options.acsUrl
            };

            const responseXml = idp.createLogoutResponse(logoutResponseOptions);
            return responseXml;
        } catch (error) {
            console.error('[SAML Service] Failed to generate logout response:', error.message);
            console.error(error);
            throw error;
        }
    }

    static encodeSAMLResponse(samlResponse) {
        return SAMLIdentityProvider.encodeResponse(samlResponse);
    }

    static decodeSAMLRequest(samlRequest) {
        try {
            return SAMLIdentityProvider.decodeRequest(samlRequest, 'redirect');
        } catch (error) {
            console.error('[SAML Service] Failed to decode SAML request:', error.message);
            return null;
        }
    }
}

